export default function WorldMap() {
  return (
    <div className="relative w-full overflow-hidden rounded-2xl border border-[var(--border)] bg-[var(--surface-1)]">
      <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_50%_40%,rgba(34,211,238,0.10),transparent_70%)]" />
      <svg
        viewBox="0 0 1000 420"
        className="relative block h-auto w-full"
        role="img"
        aria-label="World map of NeuroTechX chapters and student clubs"
      >
        <defs>
          <radialGradient id="pinGlow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="rgba(34,211,238,0.55)" />
            <stop offset="100%" stopColor="rgba(34,211,238,0)" />
          </radialGradient>
        </defs>
        <path d={LAND_PATH} fill="var(--surface-3)" stroke="var(--border-strong)" strokeWidth={0.5} />
        {CHAPTERS.map((c) => {
          const [x, y] = c.map;
          const r = c.featured ? 4.2 : 2.6;
          return (
            <a key={c.name} href={c.url} target="_blank" rel="noopener noreferrer" className="group">
              <title>{c.name} — {c.city}</title>
              {c.featured && <circle cx={x} cy={y} r={13} fill="url(#pinGlow)" />}
              <circle
                cx={x}
                cy={y}
                r={r}
                className="transition-all group-hover:r-[6]"
                fill={c.status === "restarting" ? "#fbbf24" : "var(--neuro-accent)"}
                stroke="var(--background)"
                strokeWidth={1}
              />
            </a>
          );
        })}
        {STUDENT_CLUBS.map((s) => {
          const [x, y] = s.map;
          const dot = (
            <g key={s.name}>
              <title>{s.name} — {s.school}</title>
              <circle
                cx={x}
                cy={y}
                r={2.4}
                fill="#a78bfa"
                stroke="var(--background)"
                strokeWidth={1}
              />
            </g>
          );
          return s.url ? (
            <a key={s.name} href={s.url} target="_blank" rel="noopener noreferrer">
              {dot}
            </a>
          ) : (
            dot
          );
        })}
      </svg>
    </div>
  );
}
